sys_script_include.script:
var ServiceCarWashEntitlement = Class.create();
ServiceCarWashEntitlement.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	servicecreateEntitlement: function() {
        var plan = this.getParameter('sysparm_plan1');
        var consumer = this.getParameter('sysparm_consumer1');
        var entName = "General Service – " + plan + " Plan";
        var maxCases = (plan == "Advance") ? 10 : (plan == "Premium") ? 5 : 0;

        var ent = new GlideRecord("service_entitlement");
        ent.initialize();
        ent.entitlement_name = entName;
        ent.total_units = maxCases;
		ent.remaining_units=maxCases;
        var start = new GlideDateTime();
		var end = new GlideDateTime();
		end.addYearsLocalTime(1); 
		ent.start_date = start; 
		ent.end_date = end;
		ent.business_hour="08fcd0830a0a0b2600079f56b1adb9ae";

		var gr=new GlideRecord("csm_consumer_user");
		gr.addQuery("user_name",consumer);
		gr.query();
		if(gr.next())
		{

			var g=new GlideRecord("csm_consumer");
			g.addQuery("name",gr.name);
			g.query();
			if(g.next())
			{

				ent.consumer=g.sys_id;
			}
		}
        ent.insert();


        return "created";
    }
});
